const glyph=name=>`<svg class="easy-glyph" viewBox="0 0 34 34" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${drawings[name]??drawings.paper}</svg>`;
const arrow='<svg class="easy-arrow" viewBox="0 0 20 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M10 2v18m-5-5 5 5 5-5"/></svg>';
const labels=items=>`<div class="easy-legend">${items.map(([title,text])=>`<span><strong>${esc(title)}</strong>${esc(text)}</span>`).join('')}</div>`;
const dot=(x,y,kind='blue',r=4)=>`<circle class="ink-${kind}" cx="${x}" cy="${y}" r="${r}"/>`;
const dots=(xs,kind='blue')=>xs.map(([x,y])=>dot(x,y,kind)).join('');
const line=(x1,y1,x2,y2,extra='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" ${extra}/>`;
const axes='<path class="easy-axis" d="M24 12v120h280"/>';
const chart=(description,content,legend,height=156)=>`<svg class="easy-svg" viewBox="0 0 320 ${height}" role="img" aria-label="${esc(description)}">${content}</svg>${labels(legend)}`;
function diagram(d){
  if(d.type==='flow'||d.type==='cycle')return `<ol class="easy-flow">${d.items.map(([title,text,image],i)=>`<li>${glyph(image)}<div><strong>${esc(title)}</strong><span>${esc(text)}</span></div>${i<d.items.length-1?arrow:''}</li>`).join('')}</ol>${d.type==='cycle'?`<p class="easy-loop">${glyph('refresh')}확인·개선하며 반복해요</p>`:''}${d.foot?`<p class="easy-foot">${esc(d.foot)}</p>`:''}`;
  if(d.type==='compare')return `<div class="easy-compare" style="--parts:${d.items.length}">${d.items.map(([title,text,image])=>`<div>${glyph(image)}<strong>${esc(title)}</strong><span>${esc(text)}</span></div>`).join('')}</div>`;
  if(d.type==='ladder')return `<ol class="easy-ladder">${d.items.map(([title,text],i)=>`<li style="--step:${i}"><strong>${esc(title)}</strong><span>${esc(text)}</span></li>`).join('')}</ol>`;
  if(d.type==='hub')return `<div class="easy-hub"><div class="easy-center">${glyph(d.centerIcon)}<strong>${esc(d.center)}</strong></div><ul>${d.items.map(([title,text,image])=>`<li>${glyph(image)}<span><strong>${esc(title)}</strong>${esc(text)}</span></li>`).join('')}</ul></div>`;
  if(d.type==='matrix')return `<table class="easy-matrix"><caption class="sr-only">${esc(d.caption)}</caption><thead><tr><td></td>${d.columns.map(c=>`<th scope="col">${esc(c)}</th>`).join('')}</tr></thead><tbody>${d.rows.map((r,i)=>`<tr><th scope="row">${esc(r)}</th>${d.items.slice(i*2,i*2+2).map(([title,text])=>`<td><strong>${esc(title)}</strong><span>${esc(text)}</span></td>`).join('')}</tr>`).join('')}</tbody></table>`;
  if(d.type==='funnel')return `<div class="easy-funnel">${d.items.map(([title,text],i)=>`<div style="--width:${i===1?100:72}%"><strong>${esc(title)}</strong><span>${esc(text)}</span></div>${i<2?arrow:''}`).join('')}</div>`;
  if(d.type==='tree')return `<div class="easy-tree"><strong class="easy-root">${esc(d.root)}</strong><ul style="--parts:${d.items.length}">${d.items.map(([title,text])=>`<li><strong>${esc(title)}</strong><span>${esc(text)}</span></li>`).join('')}</ul></div>`;
  if(d.type==='targets')return chart('왼쪽: 목표 중심 주변에 모인 점들로 정확도와 정밀도가 높음. 오른쪽: 중심에서 벗어나 한곳에 모인 점들로 정밀도는 높지만 정확도는 낮음.',
    [80,240].map(x=>[44,29,14].map(r=>`<circle class="easy-outline" cx="${x}" cy="75" r="${r}"/>`).join('')).join('')+dots([[75,72],[83,77],[79,82],[86,68],[234,48],[241,43],[239,51],[246,48]]),[['정확·정밀','중심에 모임'],['정밀하지만 부정확','중심에서 벗어나 모임']]);
  if(d.type==='containers')return `<div class="easy-containers"><div><strong>벡터</strong><div class="easy-slots"><span>1</span><span>2</span><span>3</span></div><p>같은 기본 자료형</p></div><div><strong>리스트</strong><div class="easy-slots"><span>1</span><span>글</span><span>표</span></div><p>다른 자료형·구조도 가능</p></div><div><strong>데이터 프레임</strong><table><thead><tr><th>이름</th><th>점수</th></tr></thead><tbody><tr><td>민지</td><td>80</td></tr><tr><td>준호</td><td>90</td></tr></tbody></table><p>열마다 자료형이 달라도 됨</p></div></div>`;
  if(d.type==='index')return `<div class="easy-index"><div class="easy-slots">${[10,20,30].map((v,i)=>`<div><small>${i+1}번</small><strong>${v}</strong></div>`).join('')}</div>${labels([['x[2]','20 선택'],['x[-2]','10, 30 선택']])}</div>`;
  if(d.type==='missing')return `<div class="easy-records"><div><strong>정상 범위 예시</strong><span>20 · 21 · 19</span></div><div><strong>결측</strong><span class="easy-blank">NA</span></div><div><strong>이상값 후보</strong><span class="easy-outlier">200</span></div></div>`;
  if(d.type==='numberline')return chart('평균 50에서 오른쪽으로 표준편차 10을 두 번 이동하면 70. 표준점수는 2.',
    '<path class="easy-axis" d="M25 78h270M55 68v20M155 68v20M255 68v20"/><path class="easy-stroke" d="M55 57Q105 16 155 57M155 57Q205 16 255 57"/>'+dot(255,78,'blue',7),[['평균 50','출발점 z=0'],['60','표준편차 1칸'],['70','표준편차 2칸']]);
  if(d.type==='mean')return `<div class="easy-mean"><div class="easy-slots">${[2,3,4,5,26].map(v=>`<span class="${v===4?'easy-median':v===26?'easy-outlier':''}">${v}</span>`).join('')}</div>${labels([['중앙값 4','정렬 후 가운데'],['평균 8','큰 값의 영향을 받음']])}</div>`;
  if(d.type==='skew')return chart('왼쪽 분포는 오른쪽에 긴 꼬리가 있어 양의 왜도. 오른쪽 분포는 왼쪽에 긴 꼬리가 있어 음의 왜도. 축은 값의 방향을 뜻하며 실제 자료가 아닌 개념도.',
    '<path class="easy-axis" d="M10 124h140M170 124h140"/><path class="easy-area" d="M10 124C23 124 25 32 45 32S60 108 145 124ZM175 124C260 108 265 32 275 32S297 124 310 124Z"/><path class="easy-stroke" d="M65 91 133 114m-8-9 8 9-12 4M256 91l-68 23m8-9-8 9 12 4"/>', [['양의 왜도','오른쪽 꼬리'],['음의 왜도','왼쪽 꼬리']]);
  if(d.type==='sets')return chart('전체 10명. 모자 4명, 안경 5명, 둘 다 2명, 둘 다 아님 3명. 모자를 쓴 4명 중 안경도 쓴 2명에 주목.',
    '<rect class="easy-outline" x="8" y="8" width="304" height="138" rx="5"/><circle class="easy-area" cx="125" cy="76" r="58"/><circle class="easy-outline" cx="199" cy="76" r="58"/>'+dots([[95,59],[95,94],[162,60],[162,88],[218,52],[233,78],[215,101],[28,31],[42,113],[284,125]]),[['모자 4명','그중 안경 2명'],['조건부 확률','2/4 = 50%']]);
  if(d.type==='sampling')return chart('왼쪽 층화: 세 반 모두에서 한 명씩 선택. 오른쪽 군집: 세 반 중 한 반 전체를 선택. 선택한 점은 진한 원, 선택하지 않은 점은 빈 원.',
    [12,175].map((x,side)=>Array.from({length:3},(_,row)=>`<rect class="easy-outline" x="${x}" y="${18+row*40}" width="132" height="32" rx="4"/>`+Array.from({length:4},(_,col)=>dot(x+20+col*30,34+row*40,(side===0?col===0:row===1)?'blue':'empty')).join('')).join('')).join(''),[['층화','각 반에서 뽑기'],['군집','일부 반을 선택']]);
  if(d.type==='confidence')return chart('세로 점선은 고정된 참 모수. 서로 다른 표본의 구간 20개 중 19개가 참 모수를 포함하는 개념 예시. 반복마다 정확히 19개를 보장한다는 뜻은 아님.',
    '<path class="easy-axis" stroke-dasharray="4 4" d="M176 5v209"/>'+Array.from({length:20},(_,i)=>{const a=i===9?52:63+(i*19)%91,b=i===9?142:195+(i*23)%93,y=12+i*10;return `<path class="${i===9?'easy-error-stroke':'easy-stroke'}" d="M${a} ${y}h${b-a}M${a} ${y-3}v6M${b} ${y-3}v6"/>`;}).join(''),[['점선','고정된 참 모수'],['20개 중 19개 포함','반복 추출의 개념 예시']],220);
  if(d.type==='decision')return `<div class="easy-decision"><div><strong>귀무가설 H₀</strong><span>“차이가 없다”라고 가정</span></div>${arrow}<div><strong>p = 0.02 ≤ α = 0.05</strong><span>귀무가설을 기각</span></div></div>${labels([['기각','가정에 반하는 증거'],['기각 못함','참임을 입증한 것은 아님']])}`;
  if(d.type==='bars')return chart('A와 B의 기대도수는 각각 10. 관측도수는 A 6, B 14. 막대의 높이는 도수이며 바닥은 0.',
    '<path class="easy-axis" d="M24 20v112h272"/><path class="easy-axis" stroke-dasharray="4 4" d="M24 60h272"/><rect class="ink-blue" x="67" y="88.8" width="52" height="43.2"/><rect class="ink-blue" x="203" y="31.2" width="52" height="100.8"/>', [['A: 실제 6','기대 10'],['B: 실제 14','기대 10']]);
  if(d.type==='correlation')return chart('왼쪽 점들은 같은 방향으로 올라가는 양의 선형 관계. 오른쪽 점들은 U자 관계로 선형 상관이 약해도 관계가 존재할 수 있음을 보여 줌. 축 X·Y의 개념도.',
    '<path class="easy-axis" d="M15 15v117h135M180 15v117h130"/>'+dots([[28,111],[45,101],[60,75],[78,85],[96,56],[114,44],[133,25],[194,29],[212,61],[229,84],[246,101],[263,84],[280,61],[298,29]]),[['양의 선형 관계','함께 증가'],['U자 관계','선형 상관만으론 부족']]);
  if(d.type==='regression')return chart('가로축 공부 시간, 세로축 점수의 개념도. 점은 실제 관측, 직선은 예측선, 점에서 선까지의 세로 점선은 잔차.',
    axes+'<path class="easy-stroke" d="M30 123 293 25"/>'+[[48,103],[93,111],[137,70],[187,53],[238,64],[280,20]].map(([x,y])=>line(x,y,x,123-(x-30)*98/263,'class="easy-error-stroke" stroke-dasharray="3 3"')+dot(x,y)).join(''),[['가로 / 세로','공부 시간 / 점수'],['점 / 선 / 세로 차이','실제값 / 예측값 / 잔차']]);
  if(d.type==='anova')return chart('세 반의 점수 예시. 가로는 반, 세로는 점수. 각 반 안 점들의 퍼짐과 각 반의 중심 사이 차이를 함께 비교.',
    axes+[[75,[[69,104],[79,89],[71,82],[81,97]]],[165,[[159,78],[172,62],[160,69],[171,83]]],[255,[[250,43],[264,59],[247,55],[262,36]]]].map(([x,ps])=>dots(ps)+line(x-18,ps.reduce((a,p)=>a+p[1],0)/ps.length,x+18,ps.reduce((a,p)=>a+p[1],0)/ps.length,'class="easy-error-stroke"')).join(''),[['반 안의 퍼짐','집단 내 변동'],['반 중심의 차이','집단 간 변동']]);
  if(d.type==='series')return chart('가로축 시간, 세로축 값의 개념도. 전체적으로 상승하는 추세에 주기적으로 오르내리는 계절 변동이 더해진 모습.',
    axes+'<path class="easy-axis" stroke-dasharray="4 4" d="M25 113 301 28"/><path class="easy-stroke" d="M25 119q11-42 23-12t23-10 23-10 23-10 23-10 23-10 23-10 23-10 23-10 23-10 23-10"/>', [['가로 / 세로','시간 / 값'],['점선 / 굴곡','추세 / 반복 변동']]);
  if(d.type==='split')return chart('처음에는 두 클래스가 섞여 있음. 분할 질문 뒤 왼쪽에는 원 클래스, 오른쪽에는 사각형 클래스가 모여 순수한 노드가 됨.',
    '<path class="easy-axis" d="M160 72v10M80 110V82h160v28"/><rect class="easy-outline" x="111" y="10" width="98" height="62" rx="5"/>'+dots([[129,28],[151,53],[187,32]])+'<rect class="ink-red" x="162" y="20" width="8" height="8"/><rect class="ink-red" x="178" y="47" width="8" height="8"/><rect class="easy-outline" x="29" y="110" width="103" height="38" rx="5"/><rect class="easy-outline" x="188" y="110" width="103" height="38" rx="5"/>'+dots([[50,129],[80,129],[110,129]])+'<rect class="ink-red" x="212" y="125" width="8" height="8"/><rect class="ink-red" x="254" y="125" width="8" height="8"/>', [['분할 전','두 클래스가 섞임'],['분할 후','같은 클래스끼리 모임']]);
  if(d.type==='ensemble')return `<div class="easy-ensemble"><div><strong>배깅</strong><div class="easy-votes">${['모형 A','모형 B','모형 C'].map(t=>`<span>${glyph('chart')}${t}</span>`).join('')}</div><p>각각 학습한 결과를 결합</p></div><div><strong>부스팅</strong><ol class="easy-chain"><li>A</li><li>B</li><li>C</li></ol><p>앞의 부족한 부분을 순차 보완</p></div></div>`;
  if(d.type==='neighbors')return chart('왼쪽 SVM 개념도는 원과 사각형 두 클래스 사이의 경계와 마진. 오른쪽 KNN은 새 점 주변의 가까운 세 사례를 참고. 좌표는 특성 공간의 개념도.',
    '<path class="easy-stroke" d="M95 17 54 135"/><path class="easy-axis" stroke-dasharray="4 4" d="M115 17 74 135M75 17 34 135"/>'+dots([[25,35],[36,61],[23,96]])+'<rect class="ink-red" x="113" y="54" width="8" height="8"/><rect class="ink-red" x="97" y="94" width="8" height="8"/><rect class="ink-red" x="132" y="117" width="8" height="8"/><circle class="easy-outline" cx="242" cy="77" r="44" stroke-dasharray="4 4"/>'+dots([[213,58],[244,51]])+'<rect class="ink-red" x="265" y="92" width="8" height="8"/>'+dot(242,77,'empty',7),[['SVM','경계·마진'],['KNN','새 점의 가까운 이웃']]);
  if(d.type==='neural')return chart('입력층 3개 노드에서 은닉층 4개, 출력층 2개 노드로 연결됨. 예측은 왼쪽에서 오른쪽, 기울기 계산은 오른쪽에서 왼쪽으로 전달.',
    [35,76,117].flatMap(y=>[22,53,84,115].map(y2=>line(42,y,160,y2,'class="easy-network"'))).join('')+[22,53,84,115].flatMap(y=>[48,91].map(y2=>line(160,y,278,y2,'class="easy-network"'))).join('')+dots([...[35,76,117].map(y=>[42,y]),...[22,53,84,115].map(y=>[160,y]),...[48,91].map(y=>[278,y])]),[['입력 → 은닉 → 출력','앞으로 예측'],['출력 → 은닉 → 입력','뒤로 기울기 계산']]);
  if(d.type==='confusion')return `<table class="easy-matrix easy-confusion"><caption class="sr-only">양성 기준을 정한 혼동행렬 예시</caption><thead><tr><td>실제 ↓<br>예측 →</td><th scope="col">양성 예측</th><th scope="col">음성 예측</th></tr></thead><tbody><tr><th scope="row">실제 양성</th><td><strong>TP 12</strong><span>찾은 양성</span></td><td><strong>FN 6</strong><span>놓친 양성</span></td></tr><tr><th scope="row">실제 음성</th><td><strong>FP 3</strong><span>잘못 고른 음성</span></td><td><strong>TN 79</strong><span>맞힌 음성</span></td></tr></tbody></table>${labels([['정밀도 80%','양성 예측 열: 12/(12+3)'],['재현율 66.7%','실제 양성 행: 12/(12+6)']])}`;
  if(d.type==='errors')return `<div class="easy-errors"><div><strong>절댓값 오차</strong><div class="easy-slots"><span>1</span><span>3</span></div><p>MAE = 2</p></div><div><strong>제곱 오차</strong><div class="easy-slots"><span>1</span><span class="easy-outlier">9</span></div><p>MSE = 5</p></div></div>${labels([['제곱의 효과','큰 오차에 더 큰 벌점'],['RMSE','√5 ≈ 2.24']])}`;
  if(d.type==='dendrogram')return chart('A와 B가 낮은 거리에서 결합, C와 D가 다른 높이에서 결합, 두 묶음은 높은 거리에서 결합. 점선 높이에서 자르면 두 군집.',
    '<path class="easy-axis" d="M27 7v136h278"/><path class="easy-stroke" d="M60 131V99h64v32M205 131V85h64v46M92 99V25h145v60"/><path class="easy-error-stroke" stroke-dasharray="4 4" d="M30 60h265"/>', [['세로축','결합 거리·비유사도'],['점선에서 자르면','두 군집']]);
  if(d.type==='clusters')return chart('두 개의 점 무리와 떨어진 한 점. K-means는 정한 중심에 모든 점을 할당하는 방식. DBSCAN은 밀집 영역을 군집으로, 떨어진 점을 잡음으로 구분할 수 있음.',
    '<ellipse class="easy-outline" cx="87" cy="85" rx="56" ry="45"/><ellipse class="easy-outline" cx="236" cy="48" rx="53" ry="36"/>'+dots([[55,77],[69,103],[82,73],[101,100],[113,67],[205,46],[224,26],[228,63],[257,35],[265,58]])+dot(184,129,'red',5)+'<path class="easy-error-stroke" d="M79 85h16m-8-8v16M228 48h16m-8-8v16"/>', [['십자','중심의 개념'],['떨어진 점','DBSCAN에서는 잡음 후보']]);
  if(d.type==='pca')return chart('비스듬히 길게 퍼진 점들. 첫 번째 축은 가장 길게 퍼진 방향, 두 번째 축은 그에 직교하는 방향. 차원 축소는 일부 정보를 잃을 수 있음.',
    '<path class="easy-stroke" d="M33 131 290 21"/><path class="easy-error-stroke" d="M136 15 190 143"/>'+dots([[57,121],[76,119],[99,95],[124,91],[149,77],[172,86],[193,56],[219,62],[245,37],[268,30]]),[['첫 번째 축','분산이 큰 방향'],['두 번째 축','첫 축과 직교']]);
  if(d.type==='baskets')return chart('100건 중 빵 40건, 우유 50건, 둘 다 30건. 겹치는 영역이 동시 구매이며 신뢰도는 빵 구매 40건을 분모로 함.',
    '<rect class="easy-outline" x="12" y="8" width="296" height="140" rx="5"/><circle class="easy-area" cx="125" cy="77" r="55"/><circle class="easy-outline" cx="196" cy="77" r="55"/>'+glyph('basket').replace('class="easy-glyph" viewBox="0 0 34 34"','x="108" y="59" width="34" height="34" viewBox="0 0 34 34"')+glyph('basket').replace('class="easy-glyph" viewBox="0 0 34 34"','x="184" y="59" width="34" height="34" viewBox="0 0 34 34"'),[['전체 100건','동시 30건 → 지지도 30%'],['빵 구매 40건','동시 30건 → 신뢰도 75%']]);
  throw new Error(`알 수 없는 도식: ${d.type}`);
}
export function renderEasyNote(id){
  const d=EASY_NOTES[id];if(!d)return '';
  return `<div class="easy-note"><figure class="easy-figure"><figcaption>${esc(d.caption)}</figcaption>${diagram(d)}</figure><p class="easy-say">${esc(d.say)}</p><p class="easy-exam"><strong>시험에서는</strong> ${esc(d.exam)}</p></div>`;
}
